f = @(t, y) -50*(y - cos(t));
[t, y] = ode23t(f, [0 1], 0);
fprintf('%.3f\n', y(end))

f = @(t, y) -100*(y - cos(t));
[t, y] = ode23tb(f, [0 1], 0);
fprintf('%.3f\n', y(end))

opts = odeset('RelTol', 1e-10, 'AbsTol', 1e-12);
[t, y] = ode78(@(t, y) -y, [0 1], 1, opts);
fprintf('%.8f %.8f\n', y(end), exp(-1))

opts = odeset('RelTol', 1e-12, 'AbsTol', 1e-14);
[t, y] = ode89(@(t, y) -y, [0 1], 1, opts);
fprintf('%.10f %.10f\n', y(end), exp(-1))

opts = odeset('RelTol', 1e-8);
odeget(opts, 'RelTol')
odeget(opts, 'AbsTol', 1e-10)

opts = odeset('RelTol', 1e-8, 'AbsTol', 1e-10, 'MaxStep', 0.1);
[t, y] = ode45(@(t, y) -y, [0 1], 1, opts);
fprintf('%.7f\n', y(end))

f = @(t, y) -y;
sol = ode45(f, [0 1], 1);
solext = odextend(sol, [], 2);
solext.x(end)
y = deval(solext, 1.5);
fprintf('%.4f %.4f\n', y, exp(-1.5))

m = 0;
pdefun = @(x, t, u, dudx) deal(1, dudx, 0);
icfun = @(x) sin(pi*x);
bcfun = @(xl, ul, xr, ur, t) deal(ul, 0, ur, 0);
x = linspace(0, 1, 11);
t = linspace(0, 0.1, 5);
sol = pdepe(m, pdefun, icfun, bcfun, x, t);
fprintf('%.3f %.3f\n', sol(end, 6, 1), exp(-pi^2*0.1))

m = 0;
x = linspace(0, 1, 11);
t = linspace(0, 0.1, 5);
sol = pdepe(m, @(x, t, u, dudx) deal(1, dudx, 0), @(x) sin(pi*x), @(xl, ul, xr, ur, t) deal(ul, 0, ur, 0), x, t);
u = pdeval(m, x, sol(end, :, 1), 0.55);
fprintf('%.3f\n', u)

F = ode;
F.ODEFcn = @(t, y) -y;
F.InitialTime = 0;
F.InitialValue = 1;
sfun = solutionFcn(F, 0, 1);
fprintf('%.4f %.4f\n', sfun(0.5), exp(-0.5))

F = ode;
F.ODEFcn = @(t, y) -y;
F.InitialTime = 0;
F.InitialValue = 1;
S = solve(F, 0, 1);
fprintf('%.4f %.4f\n', S.Solution(end), exp(-1))
